## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/liverTumorLogic.ts`

```typescript
/**
 * Liver Tumor Clinical Compass™ — Decision Support Logic
 * Based on:
 * - EASL Clinical Practice Guidelines on HCC. J Hepatol. 2025;82(2):315-374 (PMID: 39690085)
 * - AASLD Practice Guidance on HCC. Hepatology 2025 (PMID: 39992051)
 * - ESMO Clinical Practice Guideline HCC 2025 (PMID: 39986353)
 * - BCLC 2022 staging system
 */

// ─── Input Types ─────────────────────────────────────────────────────────────

export type ChildPugh = "A5" | "A6" | "B7" | "B8" | "B9" | "C10" | "C11" | "C12" | "C13" | "C14" | "C15";
export type ALBIGrade = 1 | 2 | 3;
export type ECOGStatus = 0 | 1 | 2 | 3 | 4;
export type TumorType = "hcc" | "icca" | "metastatic" | "unknown";
export type VascularInvasion = "none" | "micro" | "macro_branch" | "macro_main";
export type PortalHTN = "none" | "clinically_significant" | "severe"; // HVPG <6, 6-10, >10 mmHg
export type TACESuitability = "suitable" | "unsuitable_infiltrative" | "unsuitable_portal_occlusion" | "unsuitable_liver_function";

export interface LiverTumorInput {
  // Tumor characteristics
  tumorType: TumorType;
  tumorCount: number; // number of lesions
  maxTumorSize: number; // cm (largest lesion)
  vascularInvasion: VascularInvasion;
  extrahepatic: boolean;
  // Liver function
  childPugh: ChildPugh;
  albiGrade: ALBIGrade;
  portalHTN: PortalHTN;
  // Patient factors
  ecogPS: ECOGStatus;
  age: number;
  // Specific factors
  afpLevel: number; // ng/mL
  futureLiverRemnant: number; // % (0 if not calculated)
  priorLiverResection: boolean;
  priorAblation: boolean;
  priorTACE: boolean;
  transplantEligible: boolean;
  milanCriteria: boolean; // within Milan criteria
  // Location factors
  subcapsular: boolean;
  periHilar: boolean;
  adjacentVessel: boolean; // within 1 cm of major vessel
  // TACE suitability
  taceSuitability: TACESuitability;
}

// ─── Output Types ─────────────────────────────────────────────────────────────

export type BCLCStage = "0" | "A" | "B" | "C" | "D";
export type TreatmentModality =
  | "resection"
  | "ablation_rfa"
  | "ablation_mwa"
  | "tace"
  | "tare_y90"
  | "sbrt"
  | "transplant"
  | "systemic_first_line"
  | "systemic_second_line"
  | "best_supportive_care"
  | "multidisciplinary";

export interface LiverTumorRecommendation {
  bclcStage: BCLCStage;
  bclcLabel: string;
  primaryModality: TreatmentModality;
  primaryModalityLabel: string;
  alternativeModalities: TreatmentModality[];
  alternativeModalityLabels: string[];
  transplantBridge?: string;
  systemicRegimen?: string;
  keyWarnings: string[];
  nextSteps: string[];
  rationale: string;
  evidenceLevel: "1A" | "1B" | "2A" | "2B" | "3" | "Expert consensus";
  guidelineSource: string;
}

// ─── BCLC Staging ─────────────────────────────────────────────────────────────

export function classifyBCLC(input: LiverTumorInput): BCLCStage {
  const { ecogPS, childPugh, tumorCount, maxTumorSize, vascularInvasion, extrahepatic } = input;

  // Stage D: End-stage
  if (childPugh.startsWith("C") || ecogPS >= 3) return "D";

  // Stage C: Advanced
  if (vascularInvasion === "macro_main" || vascularInvasion === "macro_branch" || extrahepatic || ecogPS >= 2) return "C";

  // Stage 0: Very early
  if (tumorCount === 1 && maxTumorSize <= 2 && ecogPS === 0 && (childPugh === "A5" || childPugh === "A6")) return "0";

  // Stage A: Early (single or up to 3 nodules ≤3 cm)
  if (
    (tumorCount === 1 && maxTumorSize <= 5) ||
    (tumorCount <= 3 && maxTumorSize <= 3)
  ) {
    if (ecogPS <= 1 && !childPugh.startsWith("C")) return "A";
  }

  // Stage B: Intermediate (multinodular, preserved liver function)
  if (tumorCount > 1 || (tumorCount === 1 && maxTumorSize > 5)) {
    if (ecogPS <= 1 && !childPugh.startsWith("C") && !vascularInvasion.startsWith("macro") && !extrahepatic) return "B";
  }

  return "C";
}

export function getBCLCLabel(stage: BCLCStage): string {
  switch (stage) {
    case "0": return "BCLC 0 — Very Early HCC";
    case "A": return "BCLC A — Early HCC";
    case "B": return "BCLC B — Intermediate HCC";
    case "C": return "BCLC C — Advanced HCC";
    case "D": return "BCLC D — End-Stage HCC";
  }
}

export function isWithinMilan(input: LiverTumorInput): boolean {
  return (
    (input.tumorCount === 1 && input.maxTumorSize <= 5) ||
    (input.tumorCount <= 3 && input.maxTumorSize <= 3)
  );
}

export function isResectionCandidate(input: LiverTumorInput): boolean {
  const { childPugh, portalHTN, ecogPS, vascularInvasion, extrahepatic, futureLiverRemnant } = input;
  if (extrahepatic) return false;
  if (vascularInvasion === "macro_main") return false;
  if (ecogPS >= 2) return false;
  if (childPugh.startsWith("C")) return false;
  // Major resection contraindicated with significant portal HTN + Child-Pugh B
  if (portalHTN === "severe" && childPugh.startsWith("B")) return false;
  // FLR <30% is a contraindication for major resection
  if (futureLiverRemnant > 0 && futureLiverRemnant < 30) return false;
  return true;
}

export function isAblationCandidate(input: LiverTumorInput): boolean {
  const { tumorCount, maxTumorSize, childPugh, ecogPS, adjacentVessel, periHilar } = input;
  if (ecogPS >= 2) return false;
  if (childPugh.startsWith("C")) return false;
  // Standard ablation criteria: ≤3 cm (optimal), up to 5 cm with MWA
  if (maxTumorSize > 5) return false;
  if (tumorCount > 3) return false;
  return true;
}

export function isTACECandidate(input: LiverTumorInput): boolean {
  const { childPugh, ecogPS, vascularInvasion, taceSuitability, extrahepatic } = input;
  if (extrahepatic) return false;
  if (childPugh.startsWith("C")) return false;
  if (ecogPS >= 2) return false;
  if (vascularInvasion === "macro_main") return false;
  if (taceSuitability !== "suitable") return false;
  return true;
}

// ─── Main Assessment Function ─────────────────────────────────────────────────

export function assessLiverTumor(input: LiverTumorInput): LiverTumorRecommendation {
  const bclcStage = classifyBCLC(input);
  const bclcLabel = getBCLCLabel(bclcStage);
  const warnings: string[] = [];
  const nextSteps: string[] = [];

  // AFP warning
  if (input.afpLevel > 1000) {
    warnings.push("AFP >1,000 ng/mL: absolute contraindication to liver transplantation per EASL 2025 (unless AFP drops to <1,000 for ≥3 months after downstaging)");
  }
  if (input.afpLevel > 400) {
    warnings.push("AFP >400 ng/mL: associated with high risk of recurrence after resection — consider adjuvant therapy discussion");
  }
  if (input.vascularInvasion !== "none") {
    warnings.push(`Vascular invasion (${input.vascularInvasion}): significantly impacts prognosis and treatment selection`);
  }
  if (input.adjacentVessel) {
    warnings.push("Tumor adjacent to major vessel: ablation has higher risk of incomplete treatment (heat-sink effect) — consider resection or SBRT");
  }
  if (input.periHilar) {
    warnings.push("Perihilar location: ablation carries risk of biliary injury — consider SBRT or resection");
  }

  // ── BCLC D: End-stage ──
  if (bclcStage === "D") {
    return {
      bclcStage,
      bclcLabel,
      primaryModality: "best_supportive_care",
      primaryModalityLabel: "Best Supportive Care / Palliative",
      alternativeModalities: [],
      alternativeModalityLabels: [],
      keyWarnings: [...warnings, "Child-Pugh C or ECOG ≥3: curative/palliative liver-directed therapy not recommended"],
      nextSteps: [
        "Palliative care referral",
        "Liver transplant evaluation if Child-Pugh C due to cirrhosis (not tumor burden)",
        "Symptom management",
        "Nutritional support",
      ],
      rationale: "BCLC D (end-stage): median survival <3 months. Active treatment does not improve survival. Best supportive care is recommended per EASL 2025.",
      evidenceLevel: "1A",
      guidelineSource: "EASL 2025 (PMID: 39690085); AASLD 2025 (PMID: 39992051)",
    };
  }

  // ── BCLC C: Advanced ──
  if (bclcStage === "C") {
    const systemicRegimen = input.vascularInvasion === "macro_branch" || input.vascularInvasion === "macro_main"
      ? "Atezolizumab + Bevacizumab (IMbrave150) or Durvalumab + Tremelimumab (HIMALAYA) — first-line"
      : "Atezolizumab + Bevacizumab (IMbrave150) — first-line; Lenvatinib or Sorafenib if IO contraindicated";
    return {
      bclcStage,
      bclcLabel,
      primaryModality: "systemic_first_line",
      primaryModalityLabel: "Systemic Therapy (Immunotherapy-Based)",
      alternativeModalities: input.vascularInvasion === "macro_branch" ? ["sbrt"] : [],
      alternativeModalityLabels: input.vascularInvasion === "macro_branch" ? ["SBRT (for segmental/lobar PVI without extrahepatic disease)"] : [],
      systemicRegimen,
      keyWarnings: [
        ...warnings,
        "Advanced HCC: TACE not recommended as standard — systemic therapy preferred per EASL 2025",
        input.vascularInvasion === "macro_branch"
          ? "Segmental/lobar portal vein invasion: SBRT may be considered but cannot be recommended over systemic IO-based therapy"
          : "",
      ].filter(Boolean),
      nextSteps: [
        "PD-L1 testing and hepatitis B/C viral load",
        "Atezolizumab + Bevacizumab: screen for esophageal varices before starting (endoscopy if not done in past 6 months)",
        "Baseline CT chest/abdomen/pelvis for staging",
        "Multidisciplinary tumor board discussion",
        "Consider SBRT for portal vein involvement if systemic therapy contraindicated",
      ],
      rationale: "BCLC C: systemic therapy with atezolizumab+bevacizumab is first-line (IMbrave150: OS HR 0.66, PFS HR 0.59 vs sorafenib). HIMALAYA (durvalumab+tremelimumab) is an alternative.",
      evidenceLevel: "1A",
      guidelineSource: "EASL 2025 (PMID: 39690085); ESMO 2025 (PMID: 39986353)",
    };
  }

  // ── BCLC B: Intermediate ──
  if (bclcStage === "B") {
    const taceCandidate = isTACECandidate(input);
    const primaryModality: TreatmentModality = taceCandidate ? "tace" : "tare_y90";
    const alternatives: TreatmentModality[] = taceCandidate ? ["tare_y90", "sbrt"] : ["sbrt", "systemic_first_line"];
    return {
      bclcStage,
      bclcLabel,
      primaryModality,
      primaryModalityLabel: taceCandidate
        ? "TACE (cTACE or DEB-TACE) — preferred for liver-confined intermediate HCC"
        : "TARE/Y-90 (SIRT) — alternative when TACE unsuitable",
      alternativeModalities: alternatives,
      alternativeModalityLabels: taceCandidate
        ? ["TARE/Y-90 (SIRT) — alternative to TACE", "SBRT — for selected patients unsuitable for TACE/TARE"]
        : ["SBRT", "Systemic therapy (if lobar TARE not feasible)"],
      transplantBridge: input.transplantEligible && input.milanCriteria
        ? "TACE or TARE as bridge to transplant — maintain within Milan criteria"
        : undefined,
      keyWarnings: [
        ...warnings,
        !taceCandidate ? `TACE unsuitable: ${input.taceSuitability.replace(/_/g, " ")} — consider TARE/Y-90 or systemic therapy` : "",
        input.childPugh.startsWith("B")
          ? "Child-Pugh B: increased risk of hepatic decompensation after TACE — consider TARE or systemic therapy"
          : "",
      ].filter(Boolean),
      nextSteps: [
        "Multidisciplinary tumor board discussion (hepatology, IR, oncology, surgery)",
        taceCandidate
          ? "Plan TACE: selective approach preferred (cTACE or DEB-TACE — equivalent per EASL 2025)"
          : "Plan TARE/Y-90: lobar approach if feasible",
        "Liver function assessment: Child-Pugh, ALBI, bilirubin",
        "Assess for transplant eligibility if within Milan criteria",
        "Response assessment: mRECIST at 4-6 weeks post-TACE",
      ],
      rationale: "BCLC B: TACE is preferred for liver-confined intermediate HCC with preserved portal flow. TARE/Y-90 is an alternative when TACE is unsuitable. Per EASL 2025: TACE should be preferred to systemic therapy for liver-confined disease when selective approach is possible.",
      evidenceLevel: "1A",
      guidelineSource: "EASL 2025 (PMID: 39690085); AASLD 2025 (PMID: 39992051)",
    };
  }

  // ── BCLC A: Early ──
  const resectionCandidate = isResectionCandidate(input);
  const ablationCandidate = isAblationCandidate(input);

  // Very early (BCLC 0) or solitary ≤2 cm
  if (bclcStage === "0" || (input.tumorCount === 1 && input.maxTumorSize <= 2)) {
    const preferResection = resectionCandidate && !input.adjacentVessel && input.portalHTN === "none";
    const primary: TreatmentModality = preferResection ? "resection" : ablationCandidate ? "ablation_rfa" : "transplant";
    return {
      bclcStage,
      bclcLabel,
      primaryModality: primary,
      primaryModalityLabel:
        primary === "resection" ? "Liver Resection (preferred for non-cirrhotic or well-compensated cirrhosis)" :
        primary === "ablation_rfa" ? "Thermal Ablation (RFA or MWA) — equivalent to resection for ≤2 cm" :
        "Liver Transplantation",
      alternativeModalities: preferResection
        ? ["ablation_rfa", "transplant"]
        : resectionCandidate ? ["resection", "transplant"] : ["ablation_rfa"],
      alternativeModalityLabels: preferResection
        ? ["Thermal Ablation (RFA/MWA) — equivalent to resection for ≤2 cm per EASL 2025", "Liver Transplantation (if not candidate for resection/ablation)"]
        : ["Resection (if portal HTN resolves)", "Liver Transplantation"],
      transplantBridge: input.transplantEligible
        ? "Ablation as bridge to transplant — maintain within Milan criteria"
        : undefined,
      keyWarnings: [
        ...warnings,
        input.adjacentVessel
          ? "Tumor adjacent to vessel: heat-sink effect reduces ablation efficacy — consider resection or SBRT"
          : "",
        input.portalHTN === "severe" && resectionCandidate
          ? "Clinically significant portal HTN: limit resection to minor hepatectomy (≤2 segments) — avoid major resection per EASL 2025"
          : "",
      ].filter(Boolean),
      nextSteps: [
        "Liver volumetry (CT/MRI) if resection planned — ensure FLR ≥30%",
        preferResection
          ? "Minimally invasive resection (laparoscopic/robotic) preferred if technically feasible"
          : "Thermal ablation: RFA for ≤3 cm, MWA for 3-5 cm or near vessels",
        "Transplant evaluation if not candidate for resection or ablation",
        "Surveillance: CT/MRI Q3 months × 2 years after treatment",
      ],
      rationale: "BCLC 0/A: resection and ablation are recommended without preference for solitary HCC ≤2 cm per EASL 2025. For non-cirrhotic liver, resection is preferred. Transplant for patients not eligible for resection/ablation within Milan criteria.",
      evidenceLevel: "1A",
      guidelineSource: "EASL 2025 (PMID: 39690085); AASLD 2025 (PMID: 39992051)",
    };
  }

  // BCLC A: single >2 cm or up to 3 nodules ≤3 cm
  const preferResection = resectionCandidate && input.tumorCount === 1;
  const primary: TreatmentModality =
    preferResection ? "resection" :
    ablationCandidate && input.maxTumorSize <= 3 ? "ablation_rfa" :
    input.transplantEligible && input.milanCriteria ? "transplant" :
    "tace";

  nextSteps.push("Multidisciplinary tumor board discussion");
  nextSteps.push("Liver volumetry if resection planned (FLR ≥30% required)");
  if (preferResection) {
    nextSteps.push("Minimally invasive resection — laparoscopic/robotic preferred");
    nextSteps.push("Adjuvant therapy discussion: IMbrave050 did not show sustained benefit — active surveillance preferred");
  }
  if (ablationCandidate && input.maxTumorSize <= 3) {
    nextSteps.push("Thermal ablation: RFA (≤3 cm) or MWA (3-5 cm) — plan under imaging guidance");
  }
  if (input.transplantEligible && input.milanCriteria) {
    nextSteps.push("List for liver transplantation — bridge therapy (TACE/ablation) to maintain within Milan criteria");
  }

  return {
    bclcStage,
    bclcLabel,
    primaryModality: primary,
    primaryModalityLabel:
      primary === "resection" ? "Liver Resection (preferred for single HCC >2 cm with preserved liver function)" :
      primary === "ablation_rfa" ? "Thermal Ablation (RFA/MWA) — for ≤3 cm or when resection not feasible" :
      primary === "transplant" ? "Liver Transplantation (within Milan criteria)" :
      "TACE (bridge to transplant or for multinodular disease)",
    alternativeModalities: preferResection
      ? ["ablation_rfa", "transplant", "sbrt"]
      : ["resection", "transplant", "sbrt"],
    alternativeModalityLabels: preferResection
      ? ["Thermal Ablation (RFA/MWA)", "Liver Transplantation (if within Milan criteria)", "SBRT (if ablation not feasible)"]
      : ["Resection (if liver function improves)", "Liver Transplantation", "SBRT"],
    transplantBridge: input.transplantEligible && input.milanCriteria
      ? "TACE or ablation as bridge to transplant"
      : undefined,
    keyWarnings: [
      ...warnings,
      input.portalHTN === "severe" && preferResection
        ? "Clinically significant portal HTN: major resection contraindicated — consider ablation or transplant"
        : "",
      input.maxTumorSize > 3 && ablationCandidate
        ? "Tumor >3 cm: ablation has higher local recurrence risk — MWA preferred over RFA, or consider resection/SBRT"
        : "",
    ].filter(Boolean),
    nextSteps,
    rationale: "BCLC A: resection is preferred for single HCC >2 cm with preserved liver function. Ablation is equivalent to resection for ≤2 cm. Transplant for patients within Milan criteria not eligible for resection/ablation.",
    evidenceLevel: "1A",
    guidelineSource: "EASL 2025 (PMID: 39690085); AASLD 2025 (PMID: 39992051); ESMO 2025 (PMID: 39986353)",
  };
}

// ─── Utility Functions ─────────────────────────────────────────────────────────

export function getModalityColor(modality: TreatmentModality): string {
  switch (modality) {
    case "resection": return "bg-emerald-900/40 border-emerald-600 text-emerald-300";
    case "ablation_rfa":
    case "ablation_mwa": return "bg-blue-900/40 border-blue-600 text-blue-300";
    case "tace": return "bg-violet-900/40 border-violet-600 text-violet-300";
    case "tare_y90": return "bg-indigo-900/40 border-indigo-600 text-indigo-300";
    case "sbrt": return "bg-teal-900/40 border-teal-600 text-teal-300";
    case "transplant": return "bg-amber-900/40 border-amber-600 text-amber-300";
    case "systemic_first_line": return "bg-orange-900/40 border-orange-600 text-orange-300";
    case "best_supportive_care": return "bg-slate-800/50 border-slate-600 text-slate-400";
    default: return "bg-slate-800/50 border-slate-600 text-slate-400";
  }
}

export function getBCLCColor(stage: BCLCStage): string {
  switch (stage) {
    case "0": return "text-emerald-400";
    case "A": return "text-green-400";
    case "B": return "text-yellow-400";
    case "C": return "text-orange-400";
    case "D": return "text-red-400";
  }
}
